NAME = 'ACV: A Conservative Version'
BOOK = 'Micah'

CHAPTERS = {
    1: {
        1: 'Beseda Gospodova, ki je prišla Mihu iz Moraste v dneh Jotama, Ahaza in Ezekija, kraljev Judovih, ki jo je v prikazni slišal o Judi in Jeruzalemu.',
        2: 'Čujte, ljudstva vsa, in pazi, o zemlja in vse, kar je na njej! In Gospod Jehova bodi priča zoper vas, Gospod iz templja svoje svetosti!',
        3: 'Kajti glejte, Gospod prihaja iz kraja svojega in pride doli in bo stopal po višavah zemlje.',
        4: 'In gore se bodo topile pod njim in doline pokale kakor vosek pri ognju, kakor vode, ki se izlivajo po strmini.',
        5: 'Vse to se zgodi zavoljo pregrehe Jakobove in zavoljo grehov hiše Izraelove. Odkod je pregreha Jakobova? ni li iz Samarije? In odkod so višave Judove? Niso li iz Jeruzalema?',
        6: 'Zato naredim Samarijo v grobljo na polju, kakor ko hočejo zasaditi vinograd, in pomečem kamenje njeno v dolino in odkrijem njene temelje.',
        7: 'In vse njene ulite podobe se razbijejo in vsa njena darila se sežgo z ognjem, in vse malike njene razrušim; kajti nabrala jih je iz vlačugarskega plačila in v vlačugarsko plačilo se povrnejo.',
        8: 'Zato hočem plakati in tuliti, hoditi kakor oplenjen vsega in nag; zaženem plakanje kakor šakali in žalovanje kakor noji.',
        9: 'Zakaj rana njena je neozdravljiva; razlezla se je do Jude, sega prav do vrat ljudstva mojega, do Jeruzalema.',
        10: 'Ne povejte tega v Gatu, nikar ne jokajte! V Betleafri se valjam po pepelu.',
        11: 'Pojdi na ono stran, prebivalka v Šafirju, z odkrito sramoto; prebivalka v Zaananu ni šla ven; plakanje v Betezelu vam ne dopušča, da bi tam počivali.',
        12: 'Kajti prebivalka v Zarotu trepeta za svoje imetje; ker od Gospoda je prišla nesreča doli k vratom Jeruzalema.',
        13: 'Naprezi hitre konje v vozove, prebivalka v Lahisu! Ti si bila začetek greha hčeri sionski; kajti v tebi so se našle pregrehe Izraelove.',
        14: 'Zato moraš dati odpovedno darilo Morešetu v Gatu. Hiše v Akzibu bodo v prevaro kraljem Izraelovim.',
        15: 'Še ga pripeljem k tebi, prebivalka v Maresi, ki te dobi v last. Prav do Adulama pride slava Izraelova.',
        16: 'Obrij se in ostrizi se zavoljo otrok svojega veselja; razširi si plešo kakor jastreb! Kajti morali so iti od tebe v sužnost.',
    },
    2: {
        1: 'Gorje jim, ki izmišljajo krivičnost in pripravljajo hudobnost na ležiščih svojih! Ko zasveti jutro, jo izvršujejo, ker je v moči njih roke.',
        2: 'Želja jih je po njivah, pa jih ugrabijo, in po hišah, pa jih vzemo, in silo delajo možu in hiši njegovi, človeku in dediščini njegovi.',
        3: 'Zatorej pravi tako Gospod: Glej, namerjam nesrečo zoper to rodovino, ki ji ne odtegnete svojih vratov in pod katero ne boste več ošabno hodili, ker čas je hud.',
        4: 'Tisti dan začno zabavljico o vas in zapojo žalostinko: „Zgodilo se je!“bodo pravili, „docela smo opustošeni. Delež ljudstva mojega zamenja lastnika; kako ga odjemlje meni! Odpadniku razdeljuje naše njive.“',
        5: 'Zato ne boš imel nikogar, ki bi zate vrgel mersko vrvico ob žrebanju v zboru Gospodovem.',
        6: '„Ne oznanjajte!“oznanjajo lažiproroki. Ako se ne oznanja onim, ne mine sramota.',
        7: 'Se li bo reklo, hiša Jakobova, da je nagle jeze Gospod? So li takšna dejanja njegova? Niso li besede moje prijazne njemu, ki živi pošteno?',
        8: 'Še ondan se je uprlo ljudstvo moje kakor sovražnik: iznad suknje jemljete plašč njim, ki gredo brezskrbno mimo, ki so nasprotni vojski.',
        9: 'Žene ljudstva mojega podite iz hiš njih veselja, njih otročičem kradete moj kras za vselej.',
        10: 'Vstanite in pojdite! ker ta dežela ni vam počivališče zavoljo nečednosti, ki uničuje, in to s strašno pogubo.',
        11: 'Ko bi bil človek, ki se žene za vetrom in sleparsko laže: „Prorokoval ti bom o vinu in močni pijači“, ta bi bil prorok temu ljudstvu!',
        12: 'Gotovo te zberem, o Jakob, tebe vsega; gotovo skupim ostanek Izraelov; skupaj jih denem kakor ovce v Bozri, kakor čredo na njenem pašniku, da bode velik hrup od množice ljudi.',
        13: 'Prodiralec pojde gori pred njimi; proderejo in pojdejo skozi vrata in bodo skozi nje hodili ven; in njih kralj pojde pred njimi in Gospod na njih čelu.',
    },
    3: {
        1: 'In rekel sem: Čujte, prosim, glave Jakobove in knezi hiše Izraelove! Ni li vam dolžnost, da znate pravico?',
        2: 'ki sovražite dobro in ljubite hudo, trgate kožo ljudem in meso ž njih kosti;',
        3: 'ki žrete ljudstva mojega meso in jim derete kožo in lomite kosti ter jih pripravljate kakor v lonec in kakor meso, ki se deva v kotel.',
        4: 'Tedaj bodo klicali h Gospodu, pa jim ne odgovori; in skrije jim obličje svoje tisti čas primerno temu, kakor so hudobno delali.',
        5: 'Tako pravi Gospod o prorokih, ki zapeljavajo ljudstvo moje, ki kličejo, dokler imajo kaj gristi z zobmi: Mir! njemu pa, kdor jim ničesar ne da v usta, napovedujejo vojsko:',
        6: 'Zato vam pride noč, da ne boste imeli prikazni, in tema, da ne boste prorokovali; in solnce zatone prorokom ter dan jim otemni.',
        7: 'In sramovali se bodo vidci in osramočeni bodo vedeži, in vsi si zakrijejo ustnice, ker ni odgovora Božjega.',
        8: 'Jaz pa sem napolnjen z močjo po duhu Gospodovem in s sodbo in hrabrostjo, da bi oznanjal Jakobu pregreho njegovo in Izraelu njegov greh.',
        9: 'Čujte to, pravim, glave hiše Jakobove in knezi hiše Izraelove, ki studite pravo sodbo in zvijate vse, kar je ravno,',
        10: 'ki zidate Sion s krvjo in Jeruzalem s krivico!',
        11: 'Mestne glave sodijo za darila in duhovniki v njem uče za plačilo in proroki v njem vedežujejo za denar; vendar se opirajo na Gospoda in govore: Mar ni Gospod med nami? nesreča ne pride nad nas nobena!',
        12: 'Zato se bo zavoljo vas oral Sion kakor njiva in Jeruzalem postane groblja in gora hiše božje z gozdom obrastel grič.',
    },
    4: {
        1: 'In zgodi se v poslednjih dneh, da bo utrjena gora hiše Gospodove na čelu vseh gorá in povišana nad hribe; in ljudstva bodo vrela k njej.',
        2: 'In mnogi poganski narodi pojdejo in poreko: Pridite in pojdimo na goro Gospodovo in k hiši Boga Jakobovega! In učil nas bo pota svoja, in hodili bomo po njegovih stezah. Kajti s Siona pride postava in beseda Gospodova iz Jeruzalema.',
        3: 'In on bode sodnik med mnogimi ljudstvi in bo karal močne poganske narode v daljavi. In prekujejo svoje meče v orala in sulice v kosirje, ne vzdigne narod zoper narod meča in ne bodo se več učili vojske.',
        4: 'A sedeli bodo vsak pod svojo trto in pod svojo smokvo, in nihče jih ne bo strašil; kajti usta Gospoda nad vojskami so govorila.',
        5: 'Kajti vsa ljudstva hodijo, vsako v imenu svojega boga, mi pa hodimo v imenu Gospoda, Boga svojega, vedno in vekomaj.',
        6: 'Tisti dan, govori Gospod, zberem, kar je šepavo, in spravim vkup, kar je zavrženo, in nje, s katerimi sem hudo ravnal;',
        7: 'in storim tisto, kar je šepalo, za ostanek, in tisto, kar je bilo daleč zavrženo, v mogočen narod; in Gospod jim bo kraljeval na gori Sionu odslej do vekomaj.',
        8: 'In ti, stolp črede, hrib hčere sionske, do tebe dospe in k tebi pride prejšnje gospostvo, kraljestvo hčere jeruzalemske.',
        9: 'Sedaj pa zakaj toliko vpiješ? Ni li kralja v tebi? ali pa je poginil svetovalec tvoj, da so te prijele bolečine kakor porodnico?',
        10: 'Trpi bolečine in trudi se kakor porodnica, o hči sionska! kajti sedaj pojdeš ven iz mesta in boš prebivala na polju in prideš prav do Babela. Ondi boš oteta, ondi te Gospod odkupi iz pesti sovražilcev tvojih.',
        11: 'In sedaj so se zbrali zoper tebe mnogi narodi, ki pravijo: Bodi oskrunjena in oko naše naj gleda veselje svoje na Sionu!',
        12: 'Ali oni ne poznajo misli Gospodovih in ne umejo sklepa njegovega; kajti zbral jih je kakor snope na gumno.',
        13: 'Vstani in mlati, hči sionska! kajti tvoj rog napravim železen in tvoje parklje bronaste, da razmaneš mnoga ljudstva ter da posvetiš njih dobiček Gospodu in njih imetje Gospodarju vse zemlje. –',
    },
    5: {
        1: 'Sedaj pa zberi čete svoje, o hči čet! oblego so napravili zoper nas; s palico bodo tepli po licu sodnika Izraelovega.',
        2: 'In ti, Betlehem Efrata, premajhen, da bi bil med tisoči Judovimi: iz tebe mi pride tisti, ki ima biti vladar v Izraelu; njega izviri so od starodavnosti, od dni večnosti.',
        3: 'Zato jih izroči stiskalcem do časa, ko porodnica porodi; in ostanek bratov njegovih se povrne k sinovom Izraelovim.',
        4: 'In bo stal in pasel čredo svojo v moči Gospodovi, v veličastju imena Gospoda, Boga svojega. In bodo mirno prebivali; kajti sedaj bode velik do koncev zemlje.',
        5: 'In ta mož bode naš mir. Ko pride Asirec v deželo našo in ko stopi v palače naše, tedaj postavimo zoper njega sedem pastirjev in osem knezov med ljudmi.',
        6: 'In pasli bodo deželo Asirsko z mečem in deželo Nimrodovo med vrati njegovimi; in On otme nas Asircu, ko pride v deželo našo in ko stopi čez naše meje.',
        7: 'In ostanek Jakobov bode sredi mnogih narodov kakor rosa od Gospoda, kakor dež na travo, kar ne čaka nikogar in ničesar ne pričakuje od otrok človeških.',
        8: 'In ostanek Jakobov bode med poganskimi narodi, sredi mnogih ljudstev kakor lev med živalmi v gozdu, kakor mlad lev med čredami ovac, ki jih, ko gre skozi nje, tepta in trga, in ni ga, ki bi otel.',
        9: 'Povzdignjena bodi roka tvoja nad tvojimi zatiralci in vsi sovražniki tvoji naj bodo iztrebljeni!',
        10: 'In zgodi se tisti dan, govori Gospod, da iztrebim konje tvoje izsredi tebe in uničim vozove tvoje.',
        11: 'In razdenem mesta dežele tvoje in vse gradove tvoje razrušim.',
        12: 'In izničim vedeževanje iz roke tvoje in čarovnikov ne boš več imel.',
        13: 'In odpravim rezane podobe tvoje in poslikane stebre izsredi tebe, in ne boš se več klanjal rok svojih delu.',
        14: 'In izrujem Ašere, ki so sredi tebe, in pogubim mesta tvoja.',
        15: 'In maščevanje izvršim v jezi in srdu nad poganskimi narodi, ki niso poslušali.',
    },
    6: {
        1: 'Čujte vendar, kar pravi Gospod: Vstani, pravdaj se vpričo gorá in hribi naj slišijo tvoj glas!',
        2: 'Poslušajte, o gore, pravdo Gospodovo, in vi nepremični temelji zemlje! Zakaj pravdo ima Gospod z ljudstvom svojim in z Izraelom mora obračunati.',
        3: 'Ljudstvo moje, kaj sem ti storil in s čim sem ti bil nadležen? Izpričaj zoper mene!',
        4: 'Kajti pripeljal sem te gori iz dežele Egiptovske in te odrešil iz hiše sužnjev, in poslal sem pred teboj Mojzesa, Arona in Mirjamo.',
        5: 'Ljudstvo moje, spomni se vendar, kaj je imel v mislih Balak, kralj moabski, in kaj mu je odgovoril Balam, sin Beorjev; kaj se je godilo od Sitima do Gilgala, da spoznaš pravična dela Gospodova! –',
        6: 'S čim naj stopim pred Gospoda, se priklonim Bogu višave? Naj li stopim predenj z žgalnimi žrtvami, z enoletnimi teleti?',
        7: 'Ali se bo Gospod veselil tisoč ovnov, desettisoč potokov olja? Ali naj dam prvenca svojega za prestopek svoj, svojega telesa sad za greh duše svoje?',
        8: 'Naznanil ti je, o človek, kaj je dobro; in kaj zahteva Gospod od tebe, nego da strežeš pravici in ljubiš usmiljenje in da hodiš ponižno z Bogom svojim?',
        9: 'Glas Gospodov kliče mestu – in mož zdrave pameti se bo bal tvojega imena. Poslušajte šibo in njega, ki jo je pripravil!',
        10: 'So li še zakladi krivičnosti v hiši brezbožnikovi in premajhna mera, ki je prokleta?',
        11: '„Bodem li mar čist ob krivični tehtnici in če imam lažnive uteži v mošnji?“',
        12: 'Njih bogatini so polni silovitosti in njih prebivalci govore laž in imajo prevarljive jezike v ustih!',
        13: 'Zato te tudi jaz udarim neozdravljivo, te opustošim zavoljo grehov tvojih.',
        14: 'Jedel boš, pa se ne nasitiš, in prazno ti ostane v notranjščini; v stran boš spravljal, a ne otmeš ničesar; in kar otmeš, izročim meču.',
        15: 'Sejal boš, pa ne boš žel; olivke boš tlačil, a z oljem se ne boš mazilil, tudi mošt, pa vina ne boš pil.',
        16: 'Kajti drže se postav Omrijevih in ravnajo prav kakor hiša Ahabova in žive po njih svetu: zato da te izdam ljudem v strmenje in prebivalce mesta v žvižganje; in nosili boste ljudstva mojega sramoto.',
    },
    7: {
        1: 'Gorje meni! ker mi je, kakor ko so obrali sadje, kakor ko paberkujejo v vinogradu: ni ga grozda, da bi ga použil, ne zgodnje smokve, ki je želi duša moja.',
        2: 'Pobožni je izginil z zemlje in ni ga poštenjaka med ljudmi: vsi skupaj preže na kri, vsak lovi svojega brata z mrežo.',
        3: 'Po zlu sta iztegnjeni obe roki, da se jim le posreči. Knez zahteva, in sodnik sodi za plačilo, in velikaš izreka pogubo, ki je želi, in tako spletajo vse vkup.',
        4: 'Najboljši izmed njih je kakor trnov grm, najpoštenejši je kakor trnje v plotu. Dan tvojih stražarjev, tvoje obiskovanje je prišlo; sedaj nastane njih zmešnjava.',
        5: 'Ne verujte prijatelju, ne zanašajte se na zaupnika; varuj vrata svojih ust pred njo, ki ti leži v naročju!',
        6: 'Kajti sin se norčuje iz očeta, hči se upira materi, snaha tašči; sovražniki človeku so domačini njegovi.',
        7: 'A jaz bom gledal na Gospoda, čakal bom Boga rešenja svojega; usliši me Bog moj.',
        8: 'Ne veséli se nad menoj, sovražnica moja! ako sem padel, zopet vstanem; ako sedim v temi, Gospod mi je luč.',
        9: 'Srd Gospodov bom prenašal, kajti grešil sem zoper njega; dokler se ne potegne za pravdo mojo in ne izvrši sodbe zame. Privede me ven na luč, gledal bom pravičnost njegovo.',
        10: 'In videla bo to sovražnica moja, in sramota jo pokrije, ki mi je rekala: Kje je Gospod, Bog tvoj? Oči moje jo bodo z veseljem gledale: sedaj jo pogaze kakor blato na ulicah.',
        11: 'Dan pride, ko se zgrade zidovi tvoji. Tisti dan se daleč razširi tvoja meja;',
        12: 'tisti dan pridejo k tebi iz Asirije in iz mest egiptovskih in od Egipta do velereke in od morja do morja in od gore do gore.',
        13: 'In zemlja postane puščava zavoljo prebivalcev svojih, zavoljo sadu njih dejanj.',
        14: '„Pasi ljudstvo svoje s palico svojo, čredo svoje dediščine, ki osamela prebiva v gozdu, sredi Karmela; naj se pasejo v Basanu in Gileadu kakor v dneh starodavnih!“',
        15: 'Dam jim videti čudovita dela kakor v dneh, ko si šel iz dežele Egiptovske.',
        16: 'Poganski narodi bodo to videli in sram jih bode vse moči svoje; polože roke na usta, njih ušesa ogluše;',
        17: 'prah bodo lizali kakor kače, kakor laznina na zemlji; pritrepetavali bodo iz gradov svojih; s strahom se obrnejo do Gospoda, Boga našega, in bali se bodo spričo tebe.',
        18: 'Kdo je, Bog mogočni, enak tebi, ki odpuščaš krivico in izpregleduješ prestopek ostanku dediščine svoje? Ti ne držiš jeze vekomaj, ker se veseliš milosti.',
        19: 'Ti se nas vnovič usmiliš, pogaziš krivice naše; ti vržeš v morja globočino vse grehe naše.',
        20: 'Ti izkažeš resnico Jakobu in Abrahamu milost, kakor si jo prisegel očetom našim od dni starodavnih.',
    },
}
